vec4 self(vec2 uv){
return texture(iChannel1,uv)*vec4(1.0,1.0,2.0,2.0)-vec4(0.0,0.0,1.0,1.0);;
}
const float dt=0.02;
vec2 RK4(vec2 p){
    vec2 k1 = self(p).ba;
    vec2 k2 = self((p-0.5*dt*k1)).ba;
    vec2 k3 = self((p-0.5*dt*k2)).ba;
    vec2 k4 = self((p-dt*k3)).ba;
    return dt/3.*(0.5*k1+k2+k3+0.5*k4);
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    if(iFrame==0){
    fragColor.rg=fragCoord/iResolution.xy;
    fragColor.ba=vec2(0.0);
    }else{
    fragColor=self(fragCoord/iResolution.xy);
    vec2 mov=vec2(0.0);
    vec2 dat2=tex(fragCoord).rg;
    for(float x=-4.0;x<=4.0;x++){
    for(float y=-4.0;y<=4.0;y++){
    if(x!=0.0||y!=0.0){
    vec2 dat=tex(fragCoord+vec2(x,y)).rg;
    mov+=normalize(vec2(x,y))*abs(dat.r-dat2.g);
    }
    }
    }
    fragColor.ba+=mov*dt;
    fragColor.ba*=0.7;

